"""Offline references and policy checks; no expected output generated by OrbitIQ."""

import copy
import json
import math
from dataclasses import replace
from datetime import UTC, datetime, timedelta
from pathlib import Path

import numpy as np
import pytest
from astropy import units as u
from astropy.time import Time
from astropy.utils import iers
from orbitiq.orbits import coordinates
from orbitiq.orbits import earth_orientation as eo
from orbitiq.orbits.coordinates import earth_fixed, geodetic, wrap_longitude
from orbitiq.orbits.earth_orientation import (
    TransformationError,
    orientation,
    parameters,
)
from orbitiq.orbits.engine import propagate_satellite
from orbitiq.orbits.sampling import SamplingPolicy, sample_times
from sgp4.api import Satrec

REFERENCE = json.loads(
    (Path(__file__).parent / "fixtures/earth-fixed.json").read_text()
)


def state(at=REFERENCE["vallado"]["at"]):
    case = REFERENCE["vallado"]
    return {
        "at": at,
        "orbital_epoch": at,
        "frame": "TEME",
        "time_system": "UTC",
        "units": {"position": "km", "velocity": "km/s"},
        "position_km": case["position_km"],
        "velocity_km_s": case["velocity_km_s"],
    }


def published_eop_resources():
    data = eo.resources()
    case = REFERENCE["vallado"]["published_eop"]
    table = iers.IERS_B()
    table["MJD"] = [53100, 53101, 53102, 53103] * u.d
    table["UT1_UTC"] = [case["ut1_minus_utc_seconds"]] * 4 * u.s
    table["PM_x"] = [case["polar_motion_x_arcsec"]] * 4 * u.arcsec
    table["PM_y"] = [case["polar_motion_y_arcsec"]] * 4 * u.arcsec
    return replace(data, table=table)


@pytest.mark.parametrize("policy", ["bundled", "published"])
def test_vallado_teme_to_itrs_independent_reference(monkeypatch, policy):
    case = REFERENCE["vallado"]
    if policy == "published":
        fixed = published_eop_resources()
        monkeypatch.setattr(eo, "resources", lambda: fixed)
    original = state()
    result = earth_fixed(original)
    tolerances = case[
        "fixed_eop_tolerances" if policy == "published" else "bundled_eop_tolerances"
    ]
    assert result["position_km"] == pytest.approx(
        case["expected_position_km"], abs=tolerances["position_km"], rel=0
    )
    assert result["velocity_km_s"] == pytest.approx(
        case["expected_velocity_km_s"], abs=tolerances["velocity_km_s"], rel=0
    )
    assert (
        result["teme"] == original
        and result["input_frame"] == "TEME"
        and result["frame"] == "ITRS"
    )


def test_official_astropy_satellite_example_at_different_time():
    c = REFERENCE["astropy_example"]
    sat = Satrec.twoline2rv(*c["tle"])
    at = datetime.fromisoformat(c["at"])
    original = {**state(c["at"]), **propagate_satellite(sat, at)}
    result = earth_fixed(original)["geodetic"]
    for key, value in c["expected"].items():
        tol = c["tolerances"]["altitude_km" if key == "altitude_km" else "angles_deg"]
        assert result[key] == pytest.approx(value, abs=tol, rel=0)


def test_sofa_geodesy_independent_reference():
    c = REFERENCE["sofa_geodesy"]
    r = geodetic(c["position_km"])
    assert r["longitude_deg"] == pytest.approx(
        math.degrees(c["expected_longitude_rad"]), abs=1e-10, rel=0
    )
    assert r["latitude_deg"] == pytest.approx(
        math.degrees(c["expected_latitude_rad"]), abs=1e-10, rel=0
    )
    assert r["altitude_km"] == pytest.approx(
        c["expected_altitude_km"], abs=1e-10, rel=0
    )


def test_sofa_time_conversion_reference():
    c = REFERENCE["sofa_time"]
    with orientation():
        t = Time(*c["utc_jd_parts"], format="jd", scale="utc")
        t.delta_ut1_utc = c["ut1_minus_utc_seconds"]
        for scale in ("tai", "ut1"):
            expected = Time(*c[f"expected_{scale}_jd_parts"], format="jd", scale=scale)
            actual = getattr(t, scale)
            error = ((actual.jd1 - expected.jd1) + (actual.jd2 - expected.jd2)) * 86400
            assert abs(error) < c["tolerance_seconds"]


@pytest.mark.parametrize(
    "p,lat,lon,height",
    [
        ([6778.137, 0, 0], 0, 0, 400),
        ([0, 6778.137, 0], 0, 90, 400),
        ([-6778.137, 0, 0], 0, -180, 400),
        ([0, 0, 6756.752314245179], 90, 0, 400),
        ([0, 0, -6756.752314245179], -90, 0, 400),
    ],
)
def test_wgs84_analytic_axes_and_poles(p, lat, lon, height):
    r = geodetic(p)
    assert r["latitude_deg"] == pytest.approx(lat, abs=1e-10)
    assert r["longitude_deg"] == pytest.approx(lon, abs=1e-10)
    assert r["altitude_km"] == pytest.approx(height, abs=1e-9)


