def test_transformation_exception_is_sanitized(monkeypatch):
    def broken(*args):
        raise ValueError("/secret/internal")

    monkeypatch.setattr(coordinates.TEME, "transform_to", broken)
    with pytest.raises(TransformationError) as e:
        earth_fixed(state())
    assert e.value.code == "transformation_failed" and "secret" not in str(e.value)


@pytest.mark.parametrize(
    "at,code",
    [
        ("1960-01-01T00:00:00Z", "eop_out_of_range"),
        ("2028-01-01T00:00:00Z", "leap_seconds_out_of_range"),
    ],
)
def test_out_of_resource_range(at, code):
    with pytest.raises(TransformationError) as e:
        earth_fixed(state(at))
    assert e.value.code == code


def test_missing_resources_fail_without_download(monkeypatch):
    eo.resources.cache_clear()
    monkeypatch.setattr(eo.astropy_iers_data, "IERS_A_FILE", "/nonexistent/eop")
    with pytest.raises(TransformationError) as e:
        earth_fixed(state())
    assert e.value.code == "eop_unavailable" and e.value.status == 503
    eo.resources.cache_clear()


def test_bad_policy_rejected(monkeypatch):
    monkeypatch.setenv("ORBITIQ_EOP_POLICY", "assume_zero")
    with pytest.raises(TransformationError) as e:
        earth_fixed(state())
    assert e.value.code == "eop_configuration"


def test_offline_policy_restores_global_configuration(monkeypatch):
    original = iers.conf.auto_download

    def no_network(*args, **kwargs):
        raise AssertionError("Unexpected network/cache URL request")

    monkeypatch.setattr("astropy.utils.iers.iers.download_file", no_network)
    with orientation() as (data, mode):
        assert (
            not iers.conf.auto_download and iers.conf.iers_degraded_accuracy == "error"
        )
        assert (
            not iers.conf.iers_leap_second_auto_url
            and not iers.conf.ietf_leap_second_auto_url
        )
        assert iers.earth_orientation_table.get() is data.table
        assert mode in ("measured_only", "measured_or_predicted")
    earth_fixed(state())
    assert iers.conf.auto_download == original


def test_predicted_eop_is_marked_and_measured_only_rejects(monkeypatch):
    data = eo.resources()
    with orientation():
        at = Time(data.metadata["predictive_mjd"] + 2, format="mjd", scale="utc")
        now = at.to_datetime(timezone=UTC)
        r = parameters(data, at, "measured_or_predicted", now=now)
        assert r["status"] == "predicted"
        with pytest.raises(TransformationError) as e:
            parameters(data, at, "measured_only", now=now)
        assert e.value.code == "eop_prediction_disallowed"
        with pytest.raises(TransformationError) as e:
            parameters(data, at, "measured_or_predicted", now=now + timedelta(days=31))
        assert e.value.code == "eop_predictions_expired"


@pytest.mark.parametrize("bad", ["nonfinite", "missing", "bad_status"])
def test_invalid_eop_values_fail(monkeypatch, bad):
    data = eo.resources()
    table = copy.deepcopy(data.table)
    if bad == "nonfinite":

        def invalid(*args, **kwargs):
            return np.array([math.nan] * 3) * u.s, np.array([0] * 3)

        monkeypatch.setattr(table, "ut1_utc", invalid)
    elif bad == "missing":

        def missing(*args, **kwargs):
            raise ValueError("bad")

        monkeypatch.setattr(table, "pm_xy", missing)
    else:

        def bad_status(*args, **kwargs):
            return np.array([0] * 3) * u.s, np.array([999] * 3)

        monkeypatch.setattr(table, "ut1_utc", bad_status)
    with orientation(), pytest.raises(TransformationError) as e:
        parameters(
            replace(data, table=table), Time("2004-04-06", scale="utc"), "measured_only"
        )
    assert e.value.code == "eop_unavailable"


def test_unvalidated_leap_crossing_rejected():
    s = state("2017-01-01T00:01:00Z")
    s["orbital_epoch"] = "2016-12-31T23:59:00Z"
    with pytest.raises(TransformationError) as e:
        earth_fixed(s)
    assert e.value.code == "leap_crossing_unsupported"


def test_sampling_order_bounds_and_non_aligned_end():
    at = datetime(2024, 1, 1, tzinfo=UTC)
    times = sample_times(at, at + timedelta(seconds=125), 60, at, SamplingPolicy())
    assert times == [at, at + timedelta(seconds=60), at + timedelta(seconds=120)]
    assert sample_times(at, at, 60, at, SamplingPolicy()) == [at]
    assert (
        len(sample_times(at, at + timedelta(hours=6), 60, at, SamplingPolicy())) == 361
    )


@pytest.mark.parametrize(
    "start,end,step,code",
    [
        (0, -1, 60, "invalid_interval"),
        (0, 86401, 3600, "sampling_limit"),
        (0, 21601, 10, "sampling_limit"),
        (0, 60, 9, "sampling_limit"),
        (0, 60, True, "sampling_limit"),
        (0, 60, 1.5, "sampling_limit"),
        (-604801, -604800, 60, "epoch_window_exceeded"),
    ],
)
def test_sampling_invalid_requests(start, end, step, code):
    at = datetime(2024, 1, 1, tzinfo=UTC)
    with pytest.raises(TransformationError) as e:
        sample_times(
            at + timedelta(seconds=start),
            at + timedelta(seconds=end),
            step,
            at,
            SamplingPolicy(),
        )
    assert e.value.code == code


@pytest.mark.parametrize(
    "name,value",
    [
        ("ORBITIQ_TRACK_MAX_SAMPLES", "1001"),
        ("ORBITIQ_TRACK_MAX_SAMPLES", "0"),
        ("ORBITIQ_TRACK_MAX_SAMPLES", "nan"),
        ("ORBITIQ_TRACK_MAX_DURATION_SECONDS", "86401"),
        ("ORBITIQ_TRACK_MAX_DURATION_SECONDS", "0"),
    ],
)
def test_invalid_sampling_config(monkeypatch, name, value):
    monkeypatch.setenv(name, value)
    with pytest.raises(TransformationError) as e:
        SamplingPolicy.configured()
    assert e.value.code == "sampling_configuration"


def test_transform_in_fresh_process_needs_no_network_or_cache(tmp_path):
    import subprocess
    import sys

    program = """
import json, urllib.request
from astropy.utils import data
from astropy.utils.iers import iers
from orbitiq.orbits.coordinates import earth_fixed

def reject(*args, **kwargs):
    raise AssertionError("No network operation is permitted")

data.download_file = reject
iers.download_file = reject
urllib.request.urlopen = reject
state = json.loads(STATE_JSON)
result = earth_fixed(state)
assert result['earth_orientation']['auto_download'] is False
assert result['frame'] == 'ITRS'
"""
    program = program.replace("STATE_JSON", repr(json.dumps(state())))
    import os

    environment = {**os.environ, "PYTHONPATH": str(Path(__file__).resolve().parents[1])}
    run = subprocess.run(
        [sys.executable, "-c", program],
        env=environment,
        capture_output=True,
        text=True,
        timeout=10,
    )
    assert run.returncode == 0, run.stderr
    assert "Warning" not in run.stderr


def test_concurrent_transformations_restore_table_and_config():
    from concurrent.futures import ThreadPoolExecutor

    prior = iers.conf.auto_download
    with ThreadPoolExecutor(max_workers=4) as pool:
        results = list(pool.map(lambda _: earth_fixed(state()), range(8)))
    assert all(r["position_km"] == results[0]["position_km"] for r in results)
    assert iers.conf.auto_download == prior


def test_resources_restored_after_failed_transform(monkeypatch):
    original = iers.conf.auto_download
    monkeypatch.setenv("ORBITIQ_EOP_POLICY", "measured_only")
    with pytest.raises(TransformationError):
        earth_fixed(state("2028-01-01T00:00:00Z"))
    assert iers.conf.auto_download == original


